// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(uint256 initialDrugs, uint256 seedValue) public {
        address caller = address(this);
        vm.deal(caller, seedValue);

        bool ok;
        try c.seedMarket{value: seedValue}(initialDrugs) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.initialized());
        } else {
            assertTrue(!c.initialized());
        }
    }
}
